#!/usr/bin/env python3
import base64,gzip,shutil,ast
from datetime import datetime
T="/opt/vuln_intel/app/cyber_range/moduls/ui_osint.py"
B=T+".pre_patch_"+datetime.now().strftime("%Y%m%d_%H%M%S")
shutil.copy2(T,B);print("Backup:",B)
D=""
data=gzip.decompress(base64.b64decode(D))
open(T,"wb").write(data)
ast.parse(data.decode());print("OK -",data.count(10)+1,"lines")
print("Run: systemctl restart vuln-intel")
